{"command":"SCRATCH=/tmp/claude-0/-home-user-deepseek-harness--claude-worktrees-agent-ac95992e601dc9bf3/09d5aaa0-fe94-4f4a-9134-921c46b6b611/scratchpad
cat > "$SCRATCH/analyze.js" << 'EOF'
const fs = require('fs');
const lock = JSON.parse(fs.readFileSync('/root/targets/NodeGoat/package-lock.json', 'utf8'));
const audit = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));

// Build packages map: path -> {name, dependencies, devDependencies... }
const packages = lock.packages; // keys are paths like "node_modules/x" or "" for root or nested "node_modules/a/node_modules/b"

// Build resolution: for a given package "name" required from a given path context, find node_modules path via node resolution algorithm (walk up).
function resolve(fromPath, name) {
  // fromPath like "node_modules/a" or ""
  let parts = fromPath === '' ? [] : fromPath.split('node_modules/').filter(Boolean);
  // reconstruct candidate paths from deepest to shallowest
  for (let i = parts.length; i >= 0; i--) {
    const prefix = parts.slice(0, i).map(p => 'node_modules/' + p.replace(/\/$/,'')).join('');
    const candidate = (prefix ? prefix : '') + (prefix ? '/' : '') + 'node_modules/' + name;
    // normalize doubled node_modules
    const norm = candidate.replace(/node_modules\/node_modules\//g, 'node_modules/');
    if (packages[norm]) return norm;
  }
  if (packages['node_modules/' + name]) return 'node_modules/' + name;
  return null;
}

// root deps
const root = packages[''];
const directDeps = Object.assign({}, root.dependencies || {}, root.devDependencies || {});

// For each direct dep, BFS through its resolved subtree, collecting all package paths reachable.
function subtreePackages(rootPkgPath) {
  const seen = new Set();
  const queue = [rootPkgPath];
  while (queue.length) {
    const p = queue.shift();
    if (seen.has(p)) continue;
    seen.add(p);
    const pkg = packages[p];
    if (!pkg) continue;
    const deps = Object.assign({}, pkg.dependencies || {}, pkg.optionalDependencies || {});
    for (const [depName] of Object.entries(deps)) {
      const resolved = resolve(p, depName);
      if (resolved && !seen.has(resolved)) queue.push(resolved);
    }
  }
  return seen;
}

const directResults = {};
for (const [name, range] of Object.entries(directDeps)) {
  const path = resolve('', name);
  if (!path) { directResults[name] = {declaredRange: range, error: 'not resolved'}; continue; }
  const subtree = subtreePackages(path);
  directResults[name] = { declaredRange: range, path, subtreeSize: subtree.size, subtree: Array.from(subtree) };
}

// Now map vulnerable packages (from audit) to which direct deps include them in subtree
const vulnPkgs = Object.keys(audit.vulnerabilities);
const report = {};
for (const [directName, info] of Object.entries(directResults)) {
  if (info.error) { report[directName] = info; continue; }
  const subtreeNames = new Set(info.subtree.map(p => {
    const idx = p.lastIndexOf('node_modules/');
    return p.slice(idx + 'node_modules/'.length);
  }));
  const hitVulns = vulnPkgs.filter(vn => subtreeNames.has(vn));
  // gather advisory ids (GHSA urls) distinct, and severities
  const advisories = new Set();
  let maxSeverity = 'info';
  const sevOrder = {info:0, low:1, moderate:2, high:3, critical:4};
  const perPkg = {};
  for (const vn of hitVulns) {
    const v = audit.vulnerabilities[vn];
    perPkg[vn] = { severity: v.severity, isDirect: !!v.isDirect, viaCount: v.via.filter(x=>typeof x==='object').length };
    for (const via of v.via) {
      if (typeof via === 'object' && via.url) {
        advisories.add(via.url);
        if (sevOrder[via.severity] > sevOrder[maxSeverity]) maxSeverity = via.severity;
      }
    }
    if (sevOrder[v.severity] > sevOrder[maxSeverity]) maxSeverity = v.severity;
  }
  report[directName] = {
    declaredRange: directResults[directName].declaredRange,
    directPackageVulnerable: hitVulns.includes(directName),
    directOwnSeverity: audit.vulnerabilities[directName] ? audit.vulnerabilities[directName].severity : null,
    transitiveVulnCount: hitVulns.filter(n=>n!==directName).length,
    totalVulnCount: hitVulns.length,
    distinctAdvisoryCount: advisories.size,
    maxSeverity,
    vulnPackages: hitVulns,
    advisories: Array.from(advisories)
  };
}

fs.writeFileSync(process.argv[3], JSON.stringify(report, null, 2));
console.log('done');
EOF
node "$SCRATCH/analyze.js" "$SCRATCH/npm-audit.json" "$SCRATCH/grouped.json"
echo "EXIT:$?"","description":"Build script mapping vulnerable packages to owning direct dependency"}

